import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps
import re
import base64

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'dev-secret-key-change-me')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE,
        password_hash TEXT, role TEXT DEFAULT 'user',
        api_key TEXT, department TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, action TEXT,
        actor TEXT, target TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    db.commit()

def verify_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Key', '')
        if not token:
            return jsonify({'error': 'missing api key'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key = ?', (token,)).fetchone()
        if not user:
            return jsonify({'error': 'invalid api key'}), 403
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_token
def search_users():
    """Search users by department with optional role filter.
    Uses parameterized queries for department but builds dynamic
    ORDER BY clause for flexible sorting."""
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')
    sort_by = request.args.get('sort', 'username')
    sort_dir = request.args.get('dir', 'ASC')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Build query with parameterized department filter
    query = "SELECT id, username, role, department FROM users WHERE department = ?"
    params = [department]

    if role_filter:
        # Additional filter - also parameterized
        query += " AND role = ?"
        params.append(role_filter)

    # Dynamic ORDER BY - sort_by is validated against a pattern
    # but the regex allows SQL injection through crafted column expressions
    if re.match(r'^[a-zA-Z_][a-zA-Z0-9_,() ]*$', sort_by):
        query += f" ORDER BY {sort_by} {sort_dir}"
    else:
        query += f" ORDER BY username {sort_dir}"

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        # Log error but don't expose details
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['PUT'])
@verify_token
def update_notes(user_id):
    """Update user notes - admin only"""
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    data = request.get_json()
    note = data.get('note', '') if data else ''
    db = get_db()
    db.execute('UPDATE users SET department = ? WHERE id = ?', (note, user_id))
    db.commit()
    db.execute('INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
               ('update_notes', g.current_user['username'], str(user_id)))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    with app.app_context():
        init_db()
    app.run(host='0.0.0.0', port=8080)
